#ifndef GUARD_CE_TEACHABLE_H
#define GUARD_CE_TEACHABLE_H

// TM, HM and tutor compatibility as a per-species bitset in gSpeciesInfo[].teachableLearnset
// (generated by tools/ce/gen_teachable_bits.py). Slot n is bit n % 8 of byte n / 8:
//   slots 0 .. NUM_ALL_MACHINES - 1: the move gTMHMItemMoveIds[n + 1] teaches (TM01 first, then HMs)
//   slots NUM_ALL_MACHINES ..:        gCeTutorMoves[n - NUM_ALL_MACHINES]
// The website rewrites the bits, the TM moves and the tutor moves, so reassigning which
// move a TM teaches carries its compatibility with it.

#define CE_TEACHABLE_SLOTS 128
#define CE_TEACHABLE_BYTES (CE_TEACHABLE_SLOTS / 8)
#define CE_TUTOR_SLOTS     70
#define CE_TEACHABLE_TUTOR_START NUM_ALL_MACHINES

// MOVE_NONE marks an empty tutor slot.
extern const u16 gCeTutorMoves[CE_TUTOR_SLOTS];

// The move taught through teachable slot `slot`; MOVE_NONE if the slot is empty.
u32 CeTeachable_SlotMove(u32 slot);
bool32 CeTeachable_HasSlot(u32 species, u32 slot);
// Whether any TM, HM or tutor slot that teaches `move` is set for `species`.
bool32 CeTeachable_CanLearn(u32 species, u32 move);
// Fills `moves` (room for CE_TEACHABLE_SLOTS) with the species' teachable moves in slot
// order, without duplicates. Returns how many.
u32 CeTeachable_GetMoves(u32 species, u16 *moves);

#endif // GUARD_CE_TEACHABLE_H
